Section ZL6.
  Context {HCEIL : HeapCeil}.
  Variables (ra sp gp tp t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
            (F : bvmap 5 word) (fc : bv 32) (SF : Z) (m0 : mem).
  Hypothesis SFR : 0 <= SF /\ SF + 512 < 2^64.

  Definition zl6_post : machine_state -> Prop :=
    fun ms' => exists m',
      ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 (SF + 512)) (Z_to_bv 64 0) (Z_to_bv 64 (SF + 512)) a3 a4 a5 a6 a7
                    s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (Z_to_bv 64 0x9e818) fc None m' (seg_rom asegs)
      /\ u8arr asegs m' SF (repeat (Z_to_bv 8 0) 512) /\ mem_inv asegs m' /\ munch [(SF, SF + 512)] m0 m' /\ wmono asegs m0 m'.

  Lemma zl6 : forall (K : nat) (p : Z) (m : mem) (bs : list byte),
    Z.to_nat ((512 - p) / 8) = K -> 0 <= p <= 504 -> p mod 8 = 0 ->
    u8arr asegs m SF bs -> filled (Z_to_bv 8 0) bs (fun j => 0 <= j < p) -> length bs = Z.to_nat 512 ->
    mem_inv asegs m -> munch [(SF, SF + 512)] m0 m -> wmono asegs m0 m ->
    evt asegs zl6_post
      (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 (SF + p)) (Z_to_bv 64 0) (Z_to_bv 64 (SF + 512)) a3 a4 a5 a6 a7
               s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
